namespace {
import_fixture::Fixture fixture(bool flat,const char *alpha,float weight){
 import_fixture::Fixture f;f.j["nodes"][0]["translation"]={0,0,0};f.j["nodes"][0]["rotation"]={0,0,0,1};f.j["nodes"][0]["scale"]={3,3,3};f.j["nodes"][1]["translation"]={-.14f,0,0};f.j["nodes"][1]["scale"]={1,1,1};f.j["nodes"][2]["translation"]={.14f,0,0};f.j["nodes"][1]["weights"]={weight};f.j["nodes"][2]["weights"]={weight};
 auto &m=f.j["materials"][0];m.erase("extensions");m["alphaMode"]=alpha;m["pbrMetallicRoughness"]["baseColorFactor"][3]=.75f;m["pbrMetallicRoughness"]["baseColorTexture"]["texCoord"]=0;m["emissiveTexture"]={{"index",0}};m["emissiveFactor"]={.17f,.23f,.31f};
 auto png=image({230,153,204,255})->png();while(f.bin.size()%4)f.bin.push_back(0);int view=int(f.j["bufferViews"].size());f.j["bufferViews"].push_back({{"buffer",0},{"byteOffset",f.bin.size()},{"byteLength",png.size()}});f.bin.insert(f.bin.end(),png.begin(),png.end());int im=int(f.j["images"].size());f.j["images"].push_back({{"bufferView",view},{"mimeType","image/png"}});int texture=int(f.j["textures"].size());f.j["textures"].push_back({{"source",im},{"sampler",0}});m["normalTexture"]={{"index",texture},{"texCoord",0},{"scale",.6f}};
 if(flat){auto &p=f.j["meshes"][0]["primitives"][0];p["attributes"].erase("NORMAL");p["targets"][0].erase("NORMAL");}return f;
}
void paint(dome::Document &document){auto scene=document.copy_scene();auto &o=scene.active();auto mesh=o.deformation?o.deformation->preview(o.painted->mesh()):o.painted->mesh();auto local=mesh.positions[mesh.indices[0]]*.05f+mesh.positions[mesh.indices[1]]*.05f+mesh.positions[mesh.indices[2]]*.9f;auto world=scene.world_matrix(o.id).point({local.x,local.y,local.z});Vec3 p{float(world[0]),float(world[1]),float(world[2])};auto n=document.gradient(p);PaintSettings ink;ink.color={.9f,.2f,.4f,.65f};document.paint_settings(ink);NativeStrokeSample sample;sample.origin=p+n;sample.direction=n*-1.f;sample.brush.radius=.13f;check(document.begin_native_stroke()&&document.sample_native_stroke(sample),"Actual native worker paints an original UV0 source in its current morph pose");document.end_native_stroke();check(document.wait_native_stroke()&&document.wait_mesh()&&document.frame().state->error.empty(),"Painted UV0 paint commits through the real worker before independent rendering");}
}
int main(int argc,char **argv)try{
 if(argc<2)return 2;auto directory=std::filesystem::path(argv[1]);std::filesystem::create_directories(directory);NativeGraphics context;std::string vendor=reinterpret_cast<const char*>(glGetString(GL_VENDOR)),gpu=reinterpret_cast<const char*>(glGetString(GL_RENDERER));std::cout<<"GL_VENDOR "<<vendor<<"\nGL_RENDERER "<<gpu<<'\n';check(argc<3||std::string_view(argv[2])!="--hardware"||(vendor.find("Intel")!=std::string::npos&&gpu.find("A770")!=std::string::npos),"Requested independent atlas consumer runs on the actual Arc device");Fbo fbo;fbo.bind();SurfaceRenderer native;color_consumer::Renderer independent;
 for(bool flat:{false,true})for(const char *alpha:{"OPAQUE","MASK","BLEND"})for(float weight:{0.f,.65f}){
  auto f=fixture(flat,alpha,weight);auto prefix=std::string(flat?"flat-":"artist-")+alpha+"-"+std::to_string(weight);auto path=directory/(prefix+".glb");f.save(path);Scene before;before.active().visible=false;ImportAuthoringOptions options;options.paint_resolution=512;auto imported=prepare_authoring_import(before,path,options);Document document;document.replace(imported.scene);check(document.wait_mesh()&&document.frame().state->error.empty(),"Actual original UV0 import publishes immutable current render geometry");
  Pixels previous;
  for(int stage=0;stage<2;++stage){if(stage)paint(document);auto pixels=draw(native,document.frame().surface);size_t visible=0;for(size_t i=3;i<pixels.size();i+=4)visible+=pixels[i]!=0;check(visible>128,"Imported material has substantial visible coverage in the independent fixture");auto exported=directory/(prefix+"-"+std::to_string(stage)+".glb");document.export_asset(exported).get();color_consumer::Model model(exported);
    if(stage){for(size_t mesh=0;mesh<model.data->meshes_count;++mesh)for(size_t primitive=0;primitive<model.data->meshes[mesh].primitives_count;++primitive){const auto *material=model.data->meshes[mesh].primitives[primitive].material;if(!material)continue;auto *texture=material->pbr_metallic_roughness.base_color_texture.texture;if(!texture)continue;check(texture->sampler&&texture->sampler->mag_filter==cgltf_filter_type_nearest&&texture->sampler->min_filter==cgltf_filter_type_nearest_mipmap_linear,"Actual painted export retains the current nearest/mipmap sampling instead of silently replacing it with linear filtering");auto *emission=material->emissive_texture.texture;check(emission&&emission->sampler&&emission->sampler->mag_filter==cgltf_filter_type_nearest&&emission->sampler->min_filter==cgltf_filter_type_nearest_mipmap_linear&&emission->sampler->wrap_s==cgltf_wrap_mode_mirrored_repeat&&emission->sampler->wrap_t==cgltf_wrap_mode_clamp_to_edge,"Actual painted emissive texture retains its independent wrapping and filtering");}}
    fbo.bind();independent.render(model.data);auto error=delta(pixels,read());std::cout<<"PAINTED_EXPORT flat="<<flat<<" alpha="<<alpha<<" weight="<<weight<<" painted="<<stage<<" maxerror="<<error<<'\n';check(error<=2,"Independent actual-worker GLB consumer matches painted UV0 PBR, original frames, vertex colors, alpha and native paint");if(stage)check(pixels!=previous,"Native atlas painting produces a visible material change");previous=std::move(pixels);}
 }
 std::cout<<"Painted sampler render checks "<<checks<<'\n';return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}
